/**
 * Data client for the precomputed static JSON artifacts.
 *
 * All files under /data/ are generated by scripts/export_web_data.py and
 * deployed alongside the static site on Cloudflare Pages. The site renders
 * ONLY precomputed values - no model inference happens in the browser.
 */

const cache = new Map<string, Promise<unknown>>();

export function getData<T>(path: string): Promise<T> {
  const url = `${import.meta.env.BASE_URL}data/${path}`;
  if (!cache.has(url)) {
    cache.set(
      url,
      fetch(url).then((res) => {
        if (!res.ok) throw new Error(`${res.status} ${res.statusText} for ${url}`);
        return res.json() as Promise<T>;
      }).catch((error) => {
        cache.delete(url);
        throw error;
      })
    );
  }
  return cache.get(url) as Promise<T>;
}

/** Bust the in-memory cache (used by the Refresh button). */
export function invalidateCache(path?: string): void {
  if (path) cache.delete(`${import.meta.env.BASE_URL}data/${path}`);
  else cache.clear();
}
